<template>
  <view v-if="product" class="product-page safe-bottom" :class="'product-theme-' + $themeId" :style="$themeStyle">
    <swiper class="gallery" indicator-dots :indicator-active-color="$themeAccent">
      <swiper-item v-for="n in 3" :key="n"><view class="art gallery-art" :class="['art-'+product.tone,'scene-'+n]"><image v-if="product.image" class="product-image gallery-image" :src="product.image" :mode="n===1?'aspectFill':'aspectFit'"/><text v-else class="art-icon">{{product.cover}}</text><text class="gallery-no">0{{n}}</text></view></swiper-item>
    </swiper>
    <view class="product-main">
      <view class="between"><text class="product-tag">{{product.tag}}</text><text class="share icon-control" @tap="share">↗</text></view>
      <text class="title">{{product.title}}</text><text class="subtitle">{{product.subtitle}}</text>
      <view class="row price-row"><text class="price">{{product.price}}</text><text class="old-price">¥{{product.oldPrice}}</text><text class="discount">{{Math.round(product.price/product.oldPrice*10)}}折</text></view>
      <view class="sales between"><text>已售 {{product.sold}}</text><text>库存 {{product.stock}}</text><text>全场包邮</text></view>
    </view>
    <view class="choice card" @tap="sheet=true"><view><text class="label">选择</text><text>{{selectedSpec || '规格 / 数量'}}</text></view><text>›</text></view>
    <view class="choice card"><view><text class="label">送至</text><text>上海市徐汇区 · 预计明日发货</text></view><text>›</text></view>
    <view class="services"><view v-for="item in services" :key="item.title"><text class="service-icon">{{item.icon}}</text><text class="service-title">{{item.title}}</text><text>{{item.desc}}</text></view></view>
    <view class="detail-block"><text class="detail-en">STORY OF PRODUCT</text><text class="detail-title">关于这件好物</text><text class="detail-copy">{{product.desc}}</text><view class="art detail-art" :class="'art-'+product.tone"><image v-if="product.image" class="product-image" :src="product.image" mode="aspectFill"/><text v-else class="art-icon">{{product.cover}}</text></view></view>
    <view class="bottom-bar"><view class="bar-icon" @tap="home"><text class="bar-icon-mark">W</text><text>店铺</text></view><view class="bar-icon" :class="{active:fav}" @tap="favorite"><text class="bar-icon-mark">{{fav?'♥':'♡'}}</text><text>收藏</text></view><button class="cart-btn" @tap="openSheet('cart')">加入购物袋</button><button class="buy-btn" @tap="openSheet('buy')">立即购买</button></view>

    <view v-if="sheet" class="mask" @tap="sheet=false"></view>
    <view class="sku-sheet" :class="{show:sheet}"><text class="sheet-close" @tap="sheet=false">×</text><view class="row sku-product"><view class="art sku-art" :class="'art-'+product.tone"><image v-if="product.image" class="product-image" :src="product.image" mode="aspectFill"/><text v-else class="art-icon">{{product.cover}}</text></view><view><text class="price">{{product.price}}</text><text>已选：{{selectedSpec || '请选择规格'}}</text></view></view><text class="sku-label">规格</text><view class="specs"><text v-for="spec in product.specs" :key="spec" :class="{active:selectedSpec===spec}" @tap="selectedSpec=spec">{{spec}}</text></view><view class="between quantity"><text>数量</text><view class="stepper"><text @tap="quantity=Math.max(1,quantity-1)">−</text><text>{{quantity}}</text><text @tap="quantity++">＋</text></view></view><button class="btn-primary" @tap="confirm">确定</button></view>
  </view>
</template>

<script setup>
import { ref } from 'vue'; import { onLoad } from '@dcloudio/uni-app'; import { products, services } from '../../data/mock'; import { addCart, requireLogin } from '../../utils/shop'; import { isFavorite, toggleFavorite } from '../../utils/favorites'
const product=ref(null), sheet=ref(false), selectedSpec=ref(''), quantity=ref(1), action=ref('cart'), fav=ref(false)
onLoad(o=>{product.value=products.find(v=>v.id===Number(o.id))||products[0];selectedSpec.value=product.value.specs[0];fav.value=isFavorite(product.value.id)})
const openSheet=a=>{action.value=a;sheet.value=true}; const confirm=()=>{if(action.value==='cart'){addCart(product.value,selectedSpec.value,quantity.value);sheet.value=false;uni.showToast({title:'已加入购物袋'})}else{uni.setStorageSync('buy_now',[{...product.value,subtitle:selectedSpec.value,quantity:quantity.value,checked:true}]);if(requireLogin('/pages/checkout/checkout?from=buy'))uni.navigateTo({url:'/pages/checkout/checkout?from=buy'})}};
const home=()=>uni.switchTab({url:'/pages/home/home'}); const favorite=()=>{fav.value=toggleFavorite(product.value);uni.showToast({title:fav.value?'已收藏':'已取消收藏',icon:'none'})}; const share=()=>uni.showToast({title:'已生成分享卡片',icon:'none'})
</script>

<style scoped>
