.gallery{height:750rpx;background:var(--card)}.gallery-art{height:100%;background:var(--card)}.gallery-art .art-icon{font-size:220rpx}.gallery-image{background:var(--card)}.scene-2 .gallery-image{transform:scale(.88)}.scene-3 .gallery-image{transform:scale(1.08)}.gallery-no{position:absolute;z-index:4;right:30rpx;bottom:30rpx;font-family:Georgia,serif;font-size:24rpx;letter-spacing:3rpx;color:var(--ink)}
.product-main{padding:34rpx 30rpx;background:var(--card)}.product-tag{font-size:20rpx;color:var(--accent);letter-spacing:2rpx}.icon-control{display:flex;align-items:center;justify-content:center;width:58rpx;height:58rpx;border:1rpx solid var(--line);border-radius:var(--control-radius);background:var(--accent-soft);color:var(--accent);font-size:31rpx}.title,.subtitle{display:block}.title{font-size:42rpx;font-weight:700;margin-top:22rpx}.subtitle{color:var(--muted);margin-top:10rpx}.price-row{margin-top:30rpx;gap:16rpx}.price-row .price{font-size:48rpx;color:var(--accent)}.old-price{text-decoration:line-through;color:var(--muted)}.discount{background:var(--accent-soft);color:var(--accent);font-size:20rpx;padding:5rpx 10rpx;border-radius:6rpx}.sales{font-size:21rpx;color:var(--muted);border-top:1rpx solid var(--line);padding-top:25rpx;margin-top:26rpx}
.choice{margin:18rpx 28rpx 0;padding:28rpx;display:flex;justify-content:space-between;background:var(--card);border-radius:var(--card-radius)}.label{color:var(--muted);margin-right:28rpx}
.services{display:flex;justify-content:space-around;padding:30rpx 20rpx;margin-top:18rpx;background:var(--accent-soft);border-top:1rpx solid var(--line);border-bottom:1rpx solid var(--line)}.services>view{width:33.33%;text-align:center}.services text{display:block;text-align:center;font-size:19rpx}.service-icon{width:46rpx;height:46rpx;line-height:46rpx;margin:0 auto 8rpx;border-radius:var(--control-radius);background:var(--card);color:var(--accent);font-weight:700}.services .service-title{font-size:21rpx;color:var(--ink);font-weight:600}.services .service-title+text{color:var(--muted);margin-top:5rpx}
.detail-block{padding:64rpx 28rpx;background:var(--paper)}.detail-en{font-size:18rpx;letter-spacing:4rpx;color:var(--muted)}.detail-title{display:block;font-size:40rpx;font-weight:700;margin-top:14rpx}.detail-copy{display:block;line-height:1.9;color:var(--muted);margin:28rpx 0}.detail-art{height:520rpx;border-radius:var(--card-radius);background:var(--card)}.detail-art .art-icon{font-size:160rpx}
.bottom-bar{position:fixed;z-index:20;left:0;right:0;bottom:0;background:var(--card);border-top:1rpx solid var(--line);padding:14rpx 22rpx calc(14rpx + env(safe-area-inset-bottom));display:flex;align-items:center;gap:12rpx;box-shadow:0 -8rpx 28rpx rgba(0,0,0,.04)}.bar-icon{width:74rpx;text-align:center;color:var(--muted)}.bar-icon text{display:block;font-size:19rpx}.bar-icon-mark{width:46rpx;height:46rpx;line-height:44rpx;margin:0 auto 5rpx;border:1rpx solid var(--line);border-radius:var(--control-radius);background:var(--paper);color:var(--ink);font-size:24rpx!important;font-weight:700}.bar-icon.active .bar-icon-mark{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}.bottom-bar button{height:82rpx;line-height:82rpx;font-size:25rpx;margin:0;border-radius:var(--control-radius);padding:0 24rpx;font-weight:600}.cart-btn{background:var(--accent-soft);color:var(--accent);border:1rpx solid var(--accent)}.buy-btn{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));color:#fff}
.mask{position:fixed;z-index:30;inset:0;background:rgba(0,0,0,.42)}.sku-sheet{position:fixed;z-index:31;left:0;right:0;bottom:0;background:var(--card);border-radius:var(--card-radius) var(--card-radius) 0 0;padding:35rpx 30rpx calc(35rpx + env(safe-area-inset-bottom));transform:translateY(110%);transition:.25s}.sku-sheet.show{transform:translateY(0)}.sheet-close{position:absolute;right:30rpx;top:20rpx;color:var(--muted);font-size:46rpx}.sku-product{gap:24rpx}.sku-product>view:last-child text{display:block;margin-top:12rpx}.sku-product .price{font-size:38rpx;color:var(--accent)}.sku-art{width:150rpx;height:150rpx;border-radius:var(--card-radius)}.sku-art .art-icon{font-size:55rpx}.sku-label{display:block;margin:35rpx 0 20rpx}.specs{display:flex;flex-wrap:wrap;gap:16rpx}.specs text{padding:16rpx 24rpx;background:var(--paper);border:1rpx solid var(--line);border-radius:var(--control-radius);font-size:24rpx}.specs .active{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}.quantity{margin:40rpx 0}.stepper{display:flex;background:var(--paper);border:1rpx solid var(--line);border-radius:var(--control-radius);overflow:hidden}.stepper text{padding:10rpx 24rpx}
.product-theme-forest .gallery{height:690rpx;margin:20rpx 28rpx 0;border-radius:32rpx;overflow:hidden}.product-theme-forest .product-main{margin:18rpx 28rpx 0;border-radius:28rpx}.product-theme-forest .choice{border-radius:28rpx}.product-theme-forest .detail-block{margin-top:20rpx}.product-theme-forest .bottom-bar{margin:0 18rpx 18rpx;border:1rpx solid var(--line);border-radius:28rpx;padding-bottom:calc(14rpx + env(safe-area-inset-bottom))}
.product-theme-minimal .gallery{height:680rpx;border-bottom:1rpx solid var(--line)}.product-theme-minimal .product-main{border-bottom:1rpx solid var(--line)}.product-theme-minimal .choice{border:1rpx solid var(--line);box-shadow:none}.product-theme-minimal .services{background:var(--card)}.product-theme-minimal .detail-art{border:1rpx solid var(--line)}.product-theme-minimal .bottom-bar{box-shadow:none}
</style>
